<script setup lang="ts">
import { Head, Link, router, useForm, usePage } from '@inertiajs/vue3';
import { computed, ref, watch } from 'vue';
import AdminLayout from '../../../layouts/AdminLayout.vue';
import FieldError from '../../../components/FieldError.vue';
import type { PageProps } from '../../../types';

interface Address { recipient_name: string | null; phone: string | null; country_code: string | null; region: string | null; city: string | null; district: string | null; address_line_1: string | null; address_line_2: string | null; postal_code: string | null; reference: string | null }
interface Reservation { id: string; location: string; code: string; quantity: number; status: string }
interface Item { id: string; product_name: string; variant_name: string | null; sku: string; quantity: number; base_unit_price: string; discount_unit_amount: string; final_unit_price: string; line_base_total: string; line_discount_total: string; line_total: string; promotion_name: string | null; tax_category_code: string | null; tax_rate: string | null; taxable_amount: string | null; exempt_amount: string | null; unaffected_amount: string | null; tax_amount: string | null; reservations: Reservation[] }
interface History { id: string; from_status: string | null; to_status: string; reason: string | null; actor: string | null; created_at: string }
interface Order { id: string; order_number: string; checkout_session_id: string; cart_id: string | null; status: string; payment_status: string; fulfillment_status: string; currency: string; customer_name: string | null; email: string | null; phone: string | null; shipping: Address; billing: Address; delivery_type: string; subtotal_before_discounts: string; discount_total: string; subtotal: string; shipping_total: string; tax_total: string; taxable_amount: string | null; exempt_amount: string | null; unaffected_amount: string | null; tax_calculated_at: string | null; grand_total: string; placed_at: string; cancelled_at: string | null; items: Item[]; history: History[] }
interface PaymentTransaction { id: string; type: string; status: string; amount: string; occurred_at: string }
interface Payment { id: string; method: string; provider: string; status: string; amount: string; currency: string; captured_amount: string; external_reference: string | null; can_capture: boolean; can_cancel: boolean; transactions: PaymentTransaction[] }
interface PaymentData { balance: { order_total: string; captured_total: string; remaining_total: string; payment_status: string }; plan: { terms: string; total_amount: string; amount_due_now: string; amount_due_later: string; deposit_type: string | null; deposit_value: string | null; persisted: boolean }; enabled_methods: Record<'BANK_TRANSFER' | 'CASH', boolean>; can_manage: boolean; can_capture: boolean; payments: Payment[] }
interface FulfillmentSummary { id: string; status: string; location_name: string; location_code: string; item_count: number; total_quantity: number; shipment_status: string | null; created_at: string }
interface AvailableReservation { inventory_reservation_id: string; order_item_id: string; product_name: string; variant_name: string | null; sku: string; remaining_quantity: number }
interface AvailableLocation { id: string; name: string; code: string; items: AvailableReservation[] }
interface FulfillmentData { summary: { ordered_quantity: number; fulfilled_quantity: number; remaining_quantity: number; status: string }; fulfillments: FulfillmentSummary[]; available_locations: AvailableLocation[]; payment_eligibility: { eligible: boolean; reason: string | null }; can_manage: boolean; can_complete: boolean; can_manage_shipments: boolean }
interface FiscalData { can_issue: boolean; documents: { id: string; full_number: string; document_type: string; status: string; grand_total: string }[] }
interface ProfitabilityItem { order_item_id: string; product_name: string; variant_name: string | null; sku: string; ordered_quantity: number; fulfilled_quantity: number; covered_quantity: number; ordered_revenue_ex_tax: string; fulfilled_revenue_ex_tax: string; cogs: string; gross_profit: string | null; gross_margin_percent: string | null; complete: boolean }
interface Profitability { currency: string; ordered_revenue_ex_tax: string; fulfilled_revenue_ex_tax: string; cogs: string; gross_profit: string | null; gross_margin_percent: string | null; fulfilled_quantity: number; covered_quantity: number; cost_coverage_percent: string; status: string; items: ProfitabilityItem[] }
interface RelatedCustomer { id: string; display_name: string; email: string | null; phone: string | null }
interface RelatedReturn { id: string; short_id: string; status: string; requested_at: string | null; item_count: number }
interface RelatedLinks { customer: string | null; payments: string | null; refunds: string | null; returns: string | null; fulfillments: string | null }
const props = defineProps<{ order: Order; customer: RelatedCustomer | null; returns: RelatedReturn[] | null; relatedLinks: RelatedLinks; canCancel: boolean; paymentData: PaymentData | null; fulfillmentData: FulfillmentData | null; fiscalData: FiscalData | null; profitability: Profitability | null }>();
const page = usePage<PageProps>();
const status = computed(() => page.props.status);
const serverErrors = computed(() => page.props.errors as Record<string, string | undefined>);
const form = useForm({ reason: '' });
const initialMethod = props.paymentData?.enabled_methods.BANK_TRANSFER ? 'BANK_TRANSFER' : (props.paymentData?.enabled_methods.CASH ? 'CASH' : '');
const paymentForm = useForm({ method: initialMethod, amount: props.paymentData?.balance.remaining_total ?? '', external_reference: '', idempotency_key: crypto.randomUUID() });
const termsForm = useForm({ terms: props.paymentData?.plan.terms ?? 'PREPAID' });
const fulfillmentForm = useForm<{ inventory_location_id: string; items: { inventory_reservation_id: string; quantity: number }[] }>({ inventory_location_id: '', items: [] });
const canManageReturns = computed(() => page.props.currentTenantMembership?.permissions.includes('returns.manage') ?? false);
const returnForm = useForm<{ reason: string; notes: string; items: { order_item_id: string; quantity: number; reason: string }[] }>({ reason: '', notes: '', items: props.order.items.map((item) => ({ order_item_id: item.id, quantity: 0, reason: '' })) });
const fiscalForm = useForm({ document_type: 'RECEIPT', customer_document_type: '', customer_document_number: '', customer_name: props.order.customer_name ?? '', customer_address: '' });
const returnItemError = computed(() => Object.entries(returnForm.errors as Record<string, string | undefined>).find(([key]) => key.startsWith('items.'))?.[1]);
const fulfillmentQuantities = ref<Record<string, number>>({});
const cancel = () => { if (window.confirm('Cancel this order and release its active reservations?')) form.post(`/admin/orders/${props.order.id}/cancel`, { preserveScroll: true }); };
const money = (amount: string) => `${props.order.currency} ${amount}`;
const addressLines = (address: Address): string[] => [address.recipient_name, address.phone, address.address_line_1, address.address_line_2, [address.district, address.city, address.region].filter(Boolean).join(', '), [address.country_code, address.postal_code].filter(Boolean).join(' '), address.reference].filter((line): line is string => Boolean(line));
const addressTypes: ('shipping' | 'billing')[] = ['shipping', 'billing'];
const createPayment = () => paymentForm.post(`/admin/orders/${props.order.id}/payments`, { preserveScroll: true, onSuccess: () => { paymentForm.idempotency_key = crypto.randomUUID(); } });
const updateTerms = () => termsForm.patch(`/admin/orders/${props.order.id}/payment-terms`, { preserveScroll: true });
const captureKeys = new Map<string, string>();
const capture = (payment: Payment) => {
    const key = captureKeys.get(payment.id) ?? crypto.randomUUID();
    captureKeys.set(payment.id, key);
    router.post(`/admin/payments/${payment.id}/capture`, { amount: payment.amount, idempotency_key: key }, { preserveScroll: true, onSuccess: () => captureKeys.delete(payment.id) });
};
const cancelPayment = (payment: Payment) => { if (window.confirm('Cancel this pending payment?')) router.post(`/admin/payments/${payment.id}/cancel`, {}, { preserveScroll: true }); };
const createFulfillment = (location: AvailableLocation) => {
    fulfillmentForm.inventory_location_id = location.id;
    fulfillmentForm.items = location.items.map((item) => ({ inventory_reservation_id: item.inventory_reservation_id, quantity: Number(fulfillmentQuantities.value[item.inventory_reservation_id] ?? 0) })).filter((item) => item.quantity > 0);
    fulfillmentForm.post(`/admin/orders/${props.order.id}/fulfillments`, { preserveScroll: true, onSuccess: () => { fulfillmentQuantities.value = {}; } });
};
const createReturn = () => returnForm
    .transform((data) => ({ ...data, items: data.items.filter((item) => Number(item.quantity) > 0) }))
    .post(`/admin/orders/${props.order.id}/returns`, { preserveScroll: true, onSuccess: () => returnForm.reset() });
const issueFiscalDocument = () => fiscalForm.post(`/admin/orders/${props.order.id}/fiscal-document`, { preserveScroll: true });
watch(() => props.paymentData?.balance.remaining_total, (remaining) => { if (remaining) paymentForm.amount = remaining; });
</script>

<template>
    <Head :title="`Order ${order.order_number}`" />
    <AdminLayout>
        <section>
            <div class="flex flex-wrap items-end justify-between gap-5"><div><p class="font-mono text-xs tracking-[0.2em] text-emerald-800 uppercase">{{ order.status }} / {{ order.payment_status }} / {{ order.fulfillment_status }}</p><h1 class="mt-4 text-4xl font-semibold tracking-[-0.04em] sm:text-6xl">{{ order.order_number }}</h1><p class="mt-3 text-sm text-[#637067]">Placed {{ new Date(order.placed_at).toLocaleString() }}</p></div><Link href="/admin/orders" class="border border-[#17211b] px-4 py-3 text-sm font-semibold">Back to orders</Link></div>
            <p v-if="status" class="mt-6 border border-emerald-700 bg-emerald-50 p-4 text-sm font-semibold text-emerald-900">{{ status }}</p>
            <div class="mt-8 grid gap-4 sm:grid-cols-3"><article v-for="item in [['Order', order.status], ['Payment', order.payment_status], ['Fulfillment', order.fulfillment_status]]" :key="item[0]" class="border border-[#17211b]/15 bg-[#f8f5ed] p-5"><p class="text-xs uppercase text-[#637067]">{{ item[0] }}</p><p class="mt-2 font-mono text-lg font-semibold">{{ item[1] }}</p></article></div>
            <div class="mt-8 grid gap-5 lg:grid-cols-3"><article class="border border-[#17211b]/15 bg-white p-5"><h2 class="text-xl font-semibold">Buyer snapshot</h2><p class="mt-4">{{ order.customer_name ?? 'Guest' }}</p><p>{{ order.email ?? 'No email' }}</p><p>{{ order.phone ?? 'No phone' }}</p></article><article v-for="type in addressTypes" :key="type" class="border border-[#17211b]/15 bg-white p-5"><h2 class="text-xl font-semibold capitalize">{{ type }} snapshot</h2><p v-if="!addressLines(order[type]).length" class="mt-4 text-[#637067]">Not provided</p><p v-for="line in addressLines(order[type])" :key="line" class="mt-1 first:mt-4">{{ line }}</p></article></div>
            <nav v-if="relatedLinks.customer || relatedLinks.payments || relatedLinks.refunds || relatedLinks.returns || relatedLinks.fulfillments" class="mt-8 flex flex-wrap gap-3">
                <Link v-if="relatedLinks.customer" :href="relatedLinks.customer" class="border border-[#17211b] px-4 py-3 text-sm font-semibold">Customer profile</Link>
                <Link v-if="relatedLinks.payments" :href="relatedLinks.payments" class="border border-[#17211b]/40 px-4 py-3 text-sm font-semibold">All payments</Link>
                <Link v-if="relatedLinks.refunds" :href="relatedLinks.refunds" class="border border-[#17211b]/40 px-4 py-3 text-sm font-semibold">Refunds</Link>
                <Link v-if="relatedLinks.returns" :href="relatedLinks.returns" class="border border-[#17211b]/40 px-4 py-3 text-sm font-semibold">Returns</Link>
                <Link v-if="relatedLinks.fulfillments" :href="relatedLinks.fulfillments" class="border border-[#17211b]/40 px-4 py-3 text-sm font-semibold">Fulfillments</Link>
            </nav>
            <section v-if="returns" class="mt-10">
                <h2 class="text-3xl font-semibold">Returns</h2>
                <div v-if="returns.length" class="mt-5 grid gap-3 sm:grid-cols-2">
                    <Link v-for="entry in returns" :key="entry.id" :href="`/admin/returns/${entry.id}`" class="border border-[#17211b]/15 bg-[#f8f5ed] p-4">
                        <div class="flex items-center justify-between gap-3"><p class="font-mono font-semibold text-emerald-800">{{ entry.short_id }}</p><span class="bg-[#17211b] px-2 py-1 font-mono text-xs text-white">{{ entry.status }}</span></div>
                        <p class="mt-2 text-sm">{{ entry.item_count }} item lines</p>
                        <p class="mt-1 text-xs text-[#637067]">{{ entry.requested_at ? new Date(entry.requested_at).toLocaleString() : 'Not dated' }}</p>
                    </Link>
                </div>
                <p v-else class="mt-4 text-sm text-[#637067]">No returns requested for this order.</p>
            </section>
            <section class="mt-10"><h2 class="text-3xl font-semibold">Order items</h2><div class="mt-5 grid gap-4"><article v-for="item in order.items" :key="item.id" class="border border-[#17211b]/15 bg-[#f8f5ed] p-5"><div class="flex flex-wrap justify-between gap-5"><div><h3 class="text-xl font-semibold">{{ item.product_name }}</h3><p class="text-sm text-[#637067]">{{ item.variant_name ?? 'Default variant' }} / {{ item.sku }} / Qty {{ item.quantity }}</p><p v-if="item.promotion_name" class="mt-2 text-sm font-semibold text-emerald-800">{{ item.promotion_name }}</p><p v-if="item.tax_category_code" class="mt-2 font-mono text-xs">{{ item.tax_category_code }} / {{ item.tax_rate }}% / tax {{ money(item.tax_amount ?? '0.0000') }}</p></div><dl class="grid grid-cols-3 gap-5 text-sm"><div><dt>Base</dt><dd class="font-mono">{{ money(item.base_unit_price) }}</dd></div><div><dt>Discount</dt><dd class="font-mono">{{ money(item.discount_unit_amount) }}</dd></div><div><dt>Line total</dt><dd class="font-mono font-semibold">{{ money(item.line_total) }}</dd></div><div><dt>Taxable</dt><dd class="font-mono">{{ money(item.taxable_amount ?? '0.0000') }}</dd></div><div><dt>Exempt</dt><dd class="font-mono">{{ money(item.exempt_amount ?? '0.0000') }}</dd></div><div><dt>Unaffected</dt><dd class="font-mono">{{ money(item.unaffected_amount ?? '0.0000') }}</dd></div></dl></div><div class="mt-4 flex flex-wrap gap-2"><span v-for="reservation in item.reservations" :key="reservation.id" class="bg-emerald-100 px-3 py-1 text-xs font-semibold">{{ reservation.code }}: {{ reservation.quantity }} ({{ reservation.status }})</span></div></article></div></section>
            <section v-if="fiscalData" class="mt-10 border border-[#17211b]/20 bg-[#f8f5ed] p-6"><p class="font-mono text-xs tracking-[0.2em] text-emerald-800 uppercase">Tax record</p><h2 class="mt-2 text-3xl font-semibold">Fiscal documents</h2><div v-if="fiscalData.documents.length" class="mt-5 grid gap-3 sm:grid-cols-2"><Link v-for="document in fiscalData.documents" :key="document.id" :href="`/admin/fiscal-documents/${document.id}`" class="border border-[#17211b]/15 bg-white p-4"><p class="font-mono font-semibold text-emerald-800">{{ document.full_number }}</p><p class="mt-1 text-sm">{{ document.document_type }} / {{ document.status }} / {{ money(document.grand_total) }}</p></Link></div><form v-if="fiscalData.can_issue" class="mt-6 grid gap-4 border border-[#17211b]/15 bg-white p-5 sm:grid-cols-2" @submit.prevent="issueFiscalDocument"><label class="text-sm font-semibold">Document<select v-model="fiscalForm.document_type" class="mt-2 w-full border px-3 py-2"><option value="RECEIPT">BOLETA</option><option value="INVOICE">FACTURA</option></select></label><label class="text-sm font-semibold">Customer document type<input v-model="fiscalForm.customer_document_type" :required="fiscalForm.document_type === 'INVOICE'" placeholder="RUC for Factura" class="mt-2 w-full border px-3 py-2" /></label><label class="text-sm font-semibold">Customer document number<input v-model="fiscalForm.customer_document_number" :required="fiscalForm.document_type === 'INVOICE'" maxlength="80" class="mt-2 w-full border px-3 py-2" /></label><label class="text-sm font-semibold">Legal or display name<input v-model="fiscalForm.customer_name" :required="fiscalForm.document_type === 'INVOICE'" maxlength="200" class="mt-2 w-full border px-3 py-2" /></label><label v-if="fiscalForm.document_type === 'INVOICE'" class="text-sm font-semibold sm:col-span-2">Fiscal address<input v-model="fiscalForm.customer_address" required maxlength="500" class="mt-2 w-full border px-3 py-2" /></label><div class="sm:col-span-2"><p class="mb-3 text-xs text-[#637067]">Generation creates an immutable local snapshot only. Nothing is sent to SUNAT.</p><FieldError :message="fiscalForm.errors.document_type ?? fiscalForm.errors.customer_document_type ?? fiscalForm.errors.customer_document_number ?? fiscalForm.errors.customer_name ?? fiscalForm.errors.customer_address ?? serverErrors.order ?? serverErrors.issuer ?? serverErrors.series ?? serverErrors.tax_category ?? serverErrors.tax_rate" /><button :disabled="fiscalForm.processing" class="bg-[#17211b] px-5 py-3 text-sm font-semibold text-white disabled:opacity-40">Generate fiscal document</button></div></form><p v-else-if="!fiscalData.documents.length" class="mt-4 text-sm text-[#637067]">No fiscal document has been generated.</p></section>
            <form v-if="canManageReturns && order.fulfillment_status !== 'UNFULFILLED'" class="mt-10 border border-[#17211b]/20 bg-white p-6" @submit.prevent="createReturn"><p class="font-mono text-xs tracking-[0.2em] text-emerald-800 uppercase">Reverse logistics</p><h2 class="mt-2 text-3xl font-semibold">Create return</h2><p class="mt-2 text-sm text-[#637067]">Enter quantities for fulfilled items. The server verifies the currently returnable quantity.</p><div class="mt-5 grid gap-4"><div v-for="(item, index) in order.items" :key="`return-${item.id}`" class="grid gap-3 border bg-[#f8f5ed] p-4 sm:grid-cols-[1fr_7rem_1fr]"><div><p class="font-semibold">{{ item.product_name }}</p><p class="text-xs text-[#637067]">{{ item.variant_name ?? 'Default variant' }} / {{ item.sku }} / {{ item.quantity }} ordered</p></div><label class="text-sm font-semibold">Quantity<input v-model.number="returnForm.items[index].quantity" type="number" min="0" max="9999" class="mt-2 w-full border bg-white px-3 py-2 font-mono font-normal" /></label><label class="text-sm font-semibold">Item reason<input v-model="returnForm.items[index].reason" maxlength="500" class="mt-2 w-full border bg-white px-3 py-2 font-normal" /></label></div></div><div class="mt-5 grid gap-4 sm:grid-cols-2"><label class="text-sm font-semibold">Overall reason<input v-model="returnForm.reason" maxlength="500" class="mt-2 w-full border bg-white px-3 py-2 font-normal" /></label><label class="text-sm font-semibold">Internal notes<textarea v-model="returnForm.notes" maxlength="5000" class="mt-2 min-h-20 w-full border bg-white px-3 py-2 font-normal" /></label></div><FieldError :message="returnForm.errors.items ?? returnItemError ?? returnForm.errors.reason ?? returnForm.errors.notes ?? serverErrors.quantity ?? serverErrors.order" /><button :disabled="returnForm.processing" class="mt-4 bg-[#17211b] px-5 py-3 text-sm font-semibold text-white disabled:opacity-40">Create return request</button></form>
            <section v-if="fulfillmentData" class="mt-10 border border-[#17211b]/20 bg-white p-6">
                <div class="flex flex-wrap items-end justify-between gap-4"><div><p class="font-mono text-xs tracking-[0.2em] text-emerald-800 uppercase">Warehouse operations</p><h2 class="mt-2 text-3xl font-semibold">Fulfillments</h2></div><div :class="['border px-4 py-3 text-sm', fulfillmentData.payment_eligibility.eligible ? 'border-emerald-700 bg-emerald-50' : 'border-amber-700 bg-amber-50']"><span class="font-semibold">Payment {{ fulfillmentData.payment_eligibility.eligible ? 'eligible' : 'blocked' }}</span><p v-if="fulfillmentData.payment_eligibility.reason" class="mt-1 text-xs">{{ fulfillmentData.payment_eligibility.reason }}</p></div></div>
                <dl class="mt-6 grid grid-cols-2 gap-px bg-[#17211b]/15 sm:grid-cols-4"><div v-for="row in [['Ordered', fulfillmentData.summary.ordered_quantity], ['Fulfilled', fulfillmentData.summary.fulfilled_quantity], ['Remaining', fulfillmentData.summary.remaining_quantity], ['Status', fulfillmentData.summary.status]]" :key="row[0]" class="bg-[#f8f5ed] p-4"><dt class="text-xs uppercase text-[#637067]">{{ row[0] }}</dt><dd class="mt-1 font-mono text-lg font-semibold">{{ row[1] }}</dd></div></dl>
                <div class="mt-6 grid gap-3 sm:grid-cols-2"><Link v-for="fulfillment in fulfillmentData.fulfillments" :key="fulfillment.id" :href="`/admin/fulfillments/${fulfillment.id}`" class="border border-[#17211b]/15 bg-[#f8f5ed] p-4"><div class="flex items-start justify-between gap-3"><div><p class="font-semibold">{{ fulfillment.location_code }} / {{ fulfillment.location_name }}</p><p class="mt-1 text-sm text-[#637067]">{{ fulfillment.item_count }} lines / {{ fulfillment.total_quantity }} units<template v-if="fulfillment.shipment_status"> / shipment {{ fulfillment.shipment_status }}</template></p></div><span class="bg-[#17211b] px-2 py-1 font-mono text-xs text-white">{{ fulfillment.status }}</span></div></Link><p v-if="!fulfillmentData.fulfillments.length" class="text-sm text-[#637067]">No fulfillments created yet.</p></div>
                <div v-if="fulfillmentData.can_manage && fulfillmentData.available_locations.length" class="mt-8"><h3 class="text-xl font-semibold">Create from remaining reservations</h3><div class="mt-4 grid gap-5 lg:grid-cols-2"><form v-for="location in fulfillmentData.available_locations" :key="location.id" class="border border-[#17211b]/20 p-4" @submit.prevent="createFulfillment(location)"><div class="flex items-baseline justify-between gap-3"><p class="font-semibold">{{ location.name }}</p><span class="font-mono text-xs text-[#637067]">{{ location.code }}</span></div><div class="mt-4 grid gap-3"><label v-for="item in location.items" :key="item.inventory_reservation_id" class="grid grid-cols-[1fr_5rem] items-center gap-3 text-sm"><span><strong>{{ item.product_name }}</strong><br><span class="text-xs text-[#637067]">{{ item.variant_name ?? 'Default variant' }} / {{ item.sku }} / {{ item.remaining_quantity }} remaining</span></span><input v-model.number="fulfillmentQuantities[item.inventory_reservation_id]" type="number" min="0" :max="item.remaining_quantity" class="w-full border px-2 py-2 font-mono" /></label></div><FieldError :message="fulfillmentForm.errors.items ?? fulfillmentForm.errors.inventory_location_id ?? serverErrors.quantity ?? serverErrors.reservation ?? serverErrors.payment" /><button :disabled="fulfillmentForm.processing || !fulfillmentData.payment_eligibility.eligible" class="mt-4 bg-[#17211b] px-4 py-2 text-sm font-semibold text-white disabled:opacity-40">Create fulfillment</button></form></div></div>
            </section>
            <section v-if="profitability" class="mt-10 border border-[#17211b]/20 bg-[#f8f5ed] p-6"><p class="font-mono text-xs tracking-[0.2em] text-emerald-800 uppercase">Operational costing</p><h2 class="mt-2 text-3xl font-semibold">Profitability</h2><div class="mt-5 grid gap-3 sm:grid-cols-5"><div v-for="row in [['Ordered revenue', profitability.ordered_revenue_ex_tax], ['Fulfilled revenue', profitability.fulfilled_revenue_ex_tax], ['COGS', profitability.cogs], ['Gross profit', profitability.gross_profit ?? 'Incomplete'], ['Margin', profitability.gross_margin_percent === null ? 'Incomplete' : `${profitability.gross_margin_percent}%`]]" :key="row[0]" class="border bg-white p-4"><p class="text-xs text-[#637067] uppercase">{{ row[0] }}</p><p class="mt-2 font-mono font-semibold">{{ typeof row[1] === 'string' && !row[1].includes('%') && row[1] !== 'Incomplete' ? money(row[1]) : row[1] }}</p></div></div><p class="mt-4 text-sm" :class="profitability.status === 'COMPLETE' ? 'text-emerald-800' : 'text-amber-900'">Cost coverage {{ profitability.cost_coverage_percent }}% ({{ profitability.covered_quantity }} / {{ profitability.fulfilled_quantity }} fulfilled units). {{ profitability.status }}</p><div class="mt-5 overflow-x-auto"><table class="w-full min-w-[48rem] text-left text-sm"><thead><tr class="border-b text-xs uppercase text-[#637067]"><th class="py-3">Item</th><th class="text-right">Fulfilled</th><th class="text-right">Revenue</th><th class="text-right">COGS</th><th class="text-right">Gross profit</th><th class="text-right">Margin</th></tr></thead><tbody><tr v-for="item in profitability.items" :key="item.order_item_id" class="border-b"><td class="py-3 font-semibold">{{ item.product_name }}<span class="block text-xs font-normal text-[#637067]">{{ item.sku }}</span></td><td class="text-right">{{ item.fulfilled_quantity }} / {{ item.ordered_quantity }}</td><td class="text-right font-mono">{{ money(item.fulfilled_revenue_ex_tax) }}</td><td class="text-right font-mono">{{ money(item.cogs) }}</td><td class="text-right font-mono">{{ item.gross_profit === null ? 'Incomplete' : money(item.gross_profit) }}</td><td class="text-right font-mono">{{ item.gross_margin_percent === null ? 'Incomplete' : `${item.gross_margin_percent}%` }}</td></tr></tbody></table></div></section>
            <section class="mt-10 grid gap-6 lg:grid-cols-2"><article class="border border-[#17211b]/15 bg-white p-6"><h2 class="text-2xl font-semibold">Definitive totals</h2><p v-if="order.tax_calculated_at" class="mt-2 text-xs text-[#637067]">Tax calculated {{ new Date(order.tax_calculated_at).toLocaleString() }}</p><dl class="mt-5 grid gap-3"><div v-for="row in [['Before discounts', order.subtotal_before_discounts], ['Discount', order.discount_total], ['Taxable', order.taxable_amount ?? '0.0000'], ['Exempt', order.exempt_amount ?? '0.0000'], ['Unaffected', order.unaffected_amount ?? '0.0000'], ['Subtotal', order.subtotal], ['Shipping', order.shipping_total], ['Tax included', order.tax_total], ['Grand total', order.grand_total]]" :key="row[0]" class="flex justify-between border-b pb-2"><dt>{{ row[0] }}</dt><dd class="font-mono font-semibold">{{ money(row[1]) }}</dd></div></dl></article><article class="border border-[#17211b]/15 bg-white p-6"><h2 class="text-2xl font-semibold">Status history</h2><ol class="mt-5 space-y-4"><li v-for="entry in order.history" :key="entry.id" class="border-l-2 border-emerald-700 pl-4"><p class="font-mono font-semibold">{{ entry.from_status ?? 'CREATED' }} → {{ entry.to_status }}</p><p class="text-sm text-[#637067]">{{ new Date(entry.created_at).toLocaleString() }} / {{ entry.actor ?? 'System' }}</p><p v-if="entry.reason" class="mt-1 text-sm">{{ entry.reason }}</p></li></ol></article></section>
            <section v-if="paymentData" class="mt-10 border border-[#17211b]/20 bg-[#17211b] p-6 text-white">
                <div class="flex flex-wrap items-end justify-between gap-4"><div><p class="text-xs font-semibold tracking-[0.2em] text-[#d8f36a] uppercase">Financial record</p><h2 class="mt-2 text-3xl font-semibold">Payments</h2></div><div class="grid grid-cols-3 gap-5 text-right text-sm"><div><p class="text-white/60">Total</p><p class="font-mono">{{ money(paymentData.balance.order_total) }}</p></div><div><p class="text-white/60">Captured</p><p class="font-mono text-[#d8f36a]">{{ money(paymentData.balance.captured_total) }}</p></div><div><p class="text-white/60">Remaining</p><p class="font-mono">{{ money(paymentData.balance.remaining_total) }}</p></div></div></div>
                <div class="mt-6 grid gap-5 lg:grid-cols-[1fr_2fr]">
                    <div class="border border-white/20 p-4"><p class="text-xs uppercase text-white/60">Terms snapshot</p><p class="mt-2 text-xl font-semibold">{{ paymentData.plan.terms }}</p><p class="mt-2 text-sm">Due now {{ money(paymentData.plan.amount_due_now) }} / later {{ money(paymentData.plan.amount_due_later) }}</p><form v-if="paymentData.can_manage && paymentData.balance.captured_total === '0.0000'" class="mt-4 flex gap-2" @submit.prevent="updateTerms"><select v-model="termsForm.terms" class="min-w-0 flex-1 bg-white px-3 py-2 text-[#17211b]"><option value="PREPAID">PREPAID</option><option value="COD">COD</option></select><button class="border border-[#d8f36a] px-3 py-2 text-sm text-[#d8f36a]">Apply</button></form><FieldError :message="termsForm.errors.terms ?? serverErrors.payment_terms" /></div>
                    <form v-if="paymentData.can_manage" class="grid gap-3 border border-white/20 p-4 sm:grid-cols-3" @submit.prevent="createPayment"><label class="text-sm">Method<select v-model="paymentForm.method" class="mt-1 w-full bg-white px-3 py-2 text-[#17211b]"><option v-if="paymentData.enabled_methods.BANK_TRANSFER" value="BANK_TRANSFER">Bank transfer</option><option v-if="paymentData.enabled_methods.CASH" value="CASH">Cash</option></select></label><label class="text-sm">Amount<input v-model="paymentForm.amount" required inputmode="decimal" class="mt-1 w-full bg-white px-3 py-2 text-[#17211b]" /></label><label class="text-sm">Reference (optional)<input v-model="paymentForm.external_reference" maxlength="255" class="mt-1 w-full bg-white px-3 py-2 text-[#17211b]" /></label><div class="sm:col-span-3"><FieldError :message="paymentForm.errors.method ?? paymentForm.errors.amount ?? paymentForm.errors.idempotency_key ?? serverErrors.payment" /><button :disabled="paymentForm.processing || !paymentForm.method || paymentData.balance.remaining_total === '0.0000'" class="border border-[#d8f36a] px-4 py-2 text-sm font-semibold text-[#d8f36a] disabled:opacity-40">Create pending payment</button></div></form>
                </div>
                <div class="mt-6 grid gap-3"><article v-for="payment in paymentData.payments" :key="payment.id" class="border border-white/20 p-4"><div class="flex flex-wrap items-center justify-between gap-4"><div><Link :href="`/admin/payments/${payment.id}`" class="font-mono text-sm text-[#d8f36a]">{{ payment.id }}</Link><p class="mt-1 font-semibold">{{ payment.method }} / {{ payment.provider }} / {{ payment.status }}</p><p class="text-sm text-white/60">{{ money(payment.amount) }} · captured {{ money(payment.captured_amount) }}<template v-if="payment.external_reference"> · {{ payment.external_reference }}</template></p></div><div class="flex gap-2"><button v-if="payment.can_capture" class="border border-[#d8f36a] px-3 py-2 text-sm text-[#d8f36a]" @click="capture(payment)">Confirm payment</button><button v-if="payment.can_cancel" class="border border-red-300 px-3 py-2 text-sm text-red-200" @click="cancelPayment(payment)">Cancel</button></div></div><ul v-if="payment.transactions.length" class="mt-3 space-y-1 text-xs text-white/60"><li v-for="transaction in payment.transactions" :key="transaction.id">{{ transaction.type }} {{ transaction.status }} · {{ money(transaction.amount) }} · {{ new Date(transaction.occurred_at).toLocaleString() }}</li></ul></article><p v-if="!paymentData.payments.length" class="text-sm text-white/60">No payments recorded.</p></div>
            </section>
            <form v-if="canCancel" class="mt-10 border border-red-800/30 bg-red-50 p-6" @submit.prevent="cancel"><h2 class="text-2xl font-semibold text-red-900">Cancel order</h2><p class="mt-2 text-sm text-red-900">This releases active reservations. It does not reopen the cart or checkout.</p><label class="mt-4 block text-sm font-semibold">Administrative reason<textarea v-model="form.reason" required maxlength="500" class="mt-2 min-h-24 w-full border border-red-800/40 bg-white px-3 py-2" /></label><FieldError :message="form.errors.reason ?? serverErrors.order" /><button :disabled="form.processing" class="mt-4 border border-red-900 px-5 py-3 text-sm font-semibold text-red-900">Cancel order</button></form>
        </section>
    </AdminLayout>
</template>
